-- 한강 프리미엄 자동매매 V4.4 · 초기 중지 · 초단타 독립 평가 · 실제 고배율 차단
local options = ...
if type(options) ~= "table" then options = {} end
local factories = {}
factories["ui_library"] = function(env)
local encoded = [==[]==]
local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
local numbers = {} for i=1,#alphabet do numbers[alphabet:sub(i,i)]=i-1 end
local dictionary, nextCode, previous, out = {}, 256, nil, {}
local function reset() dictionary={} for i=0,255 do dictionary[i]=string.char(i) end nextCode=256 end
reset()
for i=1,#encoded,2 do
	local code=numbers[encoded:sub(i,i)]*62+numbers[encoded:sub(i+1,i+1)]
	local word=dictionary[code] or (previous and previous..previous:sub(1,1))
	assert(word,"UI 압축 복원 실패")
	out[#out+1]=word
	if previous then
		if nextCode<3844 then dictionary[nextCode]=previous..word:sub(1,1); nextCode=nextCode+1
		else reset() end
	end
	previous=word
end
local source=table.concat(out)

return assert(loadstring(source,"한강 V4.4 내장 UI LIB"))()
end
factories["analysis"] = (function()
return function(env)local config,settings=env.config,env.settings local M={}function M.finite(v)return type(v)=="number"and v==v and v>-math.huge and v<math.huge end local finite=M.finite function M.validPosition(p)return type(p)=="table"and((type(p.id)=="string"and#p.id>0 and#p.id<=128)or finite(p.id))and type(p.sym)=="string"and(p.side=="long"or p.side=="short")and finite(p.entry)and p.entry>0 and finite(p.margin)and p.margin>0 and finite(p.leverage)and p.leverage>=1 end function M.validate(c)return type(c)=="table"and finite(c.s)and finite(c.o)and finite(c.h)and finite(c.l)and finite(c.c)and c.s>0 and c.o>0 and c.l>0 and c.h>=c.c and c.l<=c.c and c.h>=c.l end function M.copy(c)return{s=c.s,o=c.o,h=c.h,l=c.l,c=c.c}end function M.copyPosition(p)return{id=p.id,sym=p.sym,side=p.side,entry=p.entry,margin=p.margin,leverage=p.leverage}end function M.toClose(stock,t)local session=config.Sessions[stock.market]if not session then return math.huge end return(session.close-config.gameMinute(t))%1440*config.GameSecondsPerMinute end function M.returns(rows)local result={}for i=2,#rows do local dt=rows[i].s-rows[i-1].s if dt>0 and dt<=config.CandleSeconds*1.5 then result[#result+1]={t=rows[i].s,r=math.log(rows[i].c/rows[i-1].c),index=i}end end return result end local function correlation(a,b)local n=math.min(#a,#b)if n<12 then return nil end local x,y,xx,yy,xy=0,0,0,0,0 for i=1,n do x=x+a[i];y=y+b[i];xx=xx+a[i]^2;yy=yy+b[i]^2;xy=xy+a[i]*b[i]end local denominator=(xx-x*x/n)*(yy-y*y/n)if denominator<=0 then return nil end return(xy-x*y/n)/math.sqrt(denominator)end M.correlation=correlation function M.crossCorrelation(a,b)local map,x,y={},{},{}for _,item in ipairs(M.returns(a))do map[item.t]=item.r end for _,item in ipairs(M.returns(b))do if map[item.t]then x[#x+1]=map[item.t];y[#y+1]=item.r end end return correlation(x,y),#x end function M.statistics(rows)local returns=M.returns(rows)local n,sum,square=#returns,0,0 for _,item in ipairs(returns)do sum=sum+item.r;square=square+item.r^2 end local mean=n>0 and sum/n or 0 local sd=n>1 and math.sqrt(math.max(0,(square-sum*sum/n)/(n-1)))or 0 local x,y,ax,ay,deviations,nextReturns={},{},{},{},{},{}local persistence,pairCount,jumps=0,0,0 local x5,y5,buckets={},{},{}for i,item in ipairs(returns)do if i>5 and item.t-returns[i-5].t==config.CandleSeconds*5 then x5[#x5+1]=returns[i-5].r;y5[#y5+1]=item.r end if type(config.gameMinute)=="function"then local bucket=tostring(math.floor(config.gameMinute(item.t)/120))local b=buckets[bucket]or{count=0,sum=0}b.count=b.count+1;b.sum=b.sum+item.r;buckets[bucket]=b end if math.abs(item.r)>math.max(0.03,sd*4)then jumps=jumps+1 end if i>1 and item.t-returns[i-1].t<=config.CandleSeconds*1.5 then local prev=returns[i-1].r x[#x+1]=prev;y[#y+1]=item.r;ax[#ax+1]=math.abs(prev);ay[#ay+1]=math.abs(item.r)pairCount=pairCount+1 if prev*item.r>0 then persistence=persistence+1 end end local k=item.index-1 if k>=20 then local average=0 for j=k-19,k do average=average+math.log(rows[j].c)end deviations[#deviations+1]=math.log(rows[k].c)-average/20 nextReturns[#nextReturns+1]=item.r end end for _,b in pairs(buckets)do b.mean=b.sum/b.count;b.sum=nil end return{bars=#rows,returns=n,mean=mean,volatility=sd,acf1=correlation(x,y),acf5=correlation(x5,y5),absoluteAcf1=correlation(ax,ay),deviationNextReturn=correlation(deviations,nextReturns),persistence=pairCount>0 and persistence/pairCount or 0,jumps=jumps,timeBuckets=buckets,approximateThreshold=n>0 and 1.96/math.sqrt(n)or nil}end function M.indicators(rows,last)last=last or#rows if last<35 then return nil end local fast,slow,gain,loss,atr,previous,oldFast,oldSlow local sum,square=0,0 for i=math.max(1,last-79),last do local c=rows[i]if not M.validate(c)or(i>1 and c.s<=rows[i-1].s)then return nil end if not fast then fast,slow,gain,loss,atr=c.c,c.c,0,0,c.h-c.l else oldFast,oldSlow=fast,slow fast=fast+(c.c-fast)*2/9;slow=slow+(c.c-slow)*2/22 local change=c.c-previous gain=(gain*13+math.max(change,0))/14;loss=(loss*13+math.max(-change,0))/14 atr=(atr*13+math.max(c.h-c.l,math.abs(c.h-previous),math.abs(c.l-previous)))/14 end if i>last-20 then sum=sum+c.c;square=square+c.c^2 end previous=c.c end local mean=sum/20 local sd=math.sqrt(math.max(0,square/20-mean^2))local rsi=loss==0 and(gain==0 and 50 or 100)or 100-100/(1+gain/loss)local c=rows[last]local volatility=atr/c.c for _,value in ipairs({fast,slow,oldFast,oldSlow,rsi,atr,mean,sd,volatility})do if not finite(value)then return nil end end local regime=volatility>0.06 and"고변동"or(volatility<config.FeeRate*3 and"저변동"or(math.abs(fast-slow)>atr*0.6 and(fast>slow and"상승 추세"or"하락 추세")or"횡보"))return{fast=fast,slow=slow,oldFast=oldFast,oldSlow=oldSlow,rsi=rsi,atr=atr,mean=mean,sd=sd,volatility=volatility,bar=c.s,close=c.c,regime=regime}end function M.signal(ind,price,strategy)if not ind or not finite(price)or price<=0 then return nil,"분석 데이터 부족 또는 비정상 시세"end if ind.atr<=0 or ind.volatility<config.FeeRate*3 then return nil,"거래 비용 대비 변동폭 부족"end if ind.volatility>0.06 then return nil,"과도한 변동성"end if math.abs(price/ind.close-1)>math.max(0.03,ind.volatility*4)then return nil,"최근 캔들 대비 급변"end local side if strategy=="trend"then if ind.fast>ind.slow and ind.oldFast>ind.oldSlow and ind.fast>ind.oldFast and ind.rsi>=53 and ind.rsi<=68 and price>=ind.fast then side="long"elseif ind.fast<ind.slow and ind.oldFast<ind.oldSlow and ind.fast<ind.oldFast and ind.rsi>=32 and ind.rsi<=47 and price<=ind.fast then side="short"end if side and math.abs(price-ind.fast)/ind.atr>1 then side=nil end if side and((side=="long"and(ind.slow<=ind.oldSlow or price<ind.close-0.5*ind.atr))or(side=="short"and(ind.slow>=ind.oldSlow or price>ind.close+0.5*ind.atr)))then side=nil end elseif strategy=="reversion"then if ind.sd>0 and price<ind.mean-2*ind.sd and ind.rsi<35 then side="long"elseif ind.sd>0 and price>ind.mean+2*ind.sd and ind.rsi>65 then side="short"end else return nil,"선택된 전략 없음"end if not side then if strategy=="trend"then local up=ind.fast>ind.slow and ind.oldFast>ind.oldSlow and ind.fast>ind.oldFast local down=ind.fast<ind.slow and ind.oldFast<ind.oldSlow and ind.fast<ind.oldFast if not up and not down then return nil,"추세 조건 미충족"end if(up and(ind.rsi<53 or ind.rsi>68))or(down and(ind.rsi<32 or ind.rsi>47))then return nil,"RSI 조건 미충족"end return nil,"추세 가격 위치 또는 EMA 이격 조건 미충족"end if ind.sd>0 and(price<ind.mean-2*ind.sd or price>ind.mean+2*ind.sd)then return nil,"RSI 조건 미충족"end return nil,"평균 회귀 가격 이탈 조건 미충족"end local stop=math.max(ind.volatility*settings.stopATR,config.FeeRate*4,0.008)local target=stop*settings.rewardRisk local cost=config.FeeRate+settings.exitFee+2*settings.slippage local score=(target-cost)/(stop+cost)if score<1.2 then return nil,"비용 반영 손익비 부족"end return{side=side,stop=stop,target=target,trail=math.max(stop,ind.volatility*settings.trailATR),score=score,strategy=strategy,bar=ind.bar,diagnostics={rsi=ind.rsi,atr=ind.atr,volatility=ind.volatility,fast=ind.fast,slow=ind.slow,quote=price,close=ind.close,emaGapATR=math.abs(price-ind.fast)/ind.atr,bar=ind.bar},reason=string.format("%s · RSI %.1f · ATR %.2f%% · 가정 손익비 %.2f",strategy=="trend"and"EMA 추세"or"평균 회귀(실험)",ind.rsi,ind.volatility*100,score)}end function M.size(capital,cash,item,leverage,usedMargin,usedRisk)local cost=config.FeeRate+settings.exitFee+2*settings.slippage local risk=math.max(0,math.min(capital*settings.risk/100,capital*settings.aggregateRisk/100-(usedRisk or 0)))return math.floor(math.max(0,math.min(risk/(leverage*(item.stop+cost)),capital*settings.allocation/100,capital*settings.totalAllocation/100-(usedMargin or 0),cash*0.9/(1+leverage*config.FeeRate))))end function M.mark(p,owned,price,actual)if owned.strategy=="quick"and env.quick then return env.quick.Mark(p,owned,price,actual)end local direction=p.side=="long"and 1 or-1 local move=direction*(price/p.entry-1)local gross=math.max(-p.margin,p.margin*p.leverage*move)local exitFee=p.margin*p.leverage*settings.exitFee*(price/p.entry)return gross-owned.entryFee-exitFee,move,gross,exitFee end function M.exit(p,owned,price,now,stock,indicator)if owned.strategy=="quick"and env.quick then return env.quick.Exit(p,owned,price,now,stock)end local net,move=M.mark(p,owned,price)owned.best=math.max(owned.best or 0,move)owned.stopMove=owned.stopMove or-owned.stop local cost=(owned.entryFee/(p.margin*p.leverage))+settings.exitFee*(price/p.entry)+settings.slippage if owned.best>=owned.stop*1.2+cost then local distance=math.max(owned.trail,indicator and indicator.volatility*settings.trailATR or owned.trail)owned.stopMove=math.max(owned.stopMove,cost+0.001,owned.best-distance)end if move<=owned.stopMove then return owned.stopMove>-owned.stop and"추적 손절"or"손절",net end if move>=owned.target+cost then return"비용 반영 익절",net end if M.toClose(stock,now)<=settings.closeBuffer then return"장 마감 여유 청산",net end if now-owned.opened>=settings.maxHold then return"보유 시간 제한",net end return nil,net end function M.metrics(capital)return{capital=capital,equity=capital,peak=capital,drawdown=0,trades=0,wins=0,losses=0,profit=0,loss=0,realized=0,streak=0,maxStreak=0,unknown=0}end function M.record(m,net)m.trades=m.trades+1;m.realized=m.realized+net if net>0 then m.wins=m.wins+1;m.profit=m.profit+net;m.streak=0 elseif net<0 then m.losses=m.losses+1;m.loss=m.loss-net;m.streak=m.streak+1;m.maxStreak=math.max(m.maxStreak,m.streak)end end function M.equityMetrics(m,value)m.equity=value;m.peak=math.max(m.peak,value)m.drawdown=math.max(m.drawdown,(m.peak-value)/math.max(m.peak,1))end function M.summary(m)return{trades=m.trades,wins=m.wins,losses=m.losses,winRate=m.trades>0 and m.wins/m.trades or 0,net=m.realized,profitFactor=m.loss>0 and m.profit/m.loss or nil,noLoss=m.loss==0,drawdown=m.drawdown,returnRate=(m.equity/m.capital-1),average=m.trades>0 and m.realized/m.trades or 0,averageWin=m.wins>0 and m.profit/m.wins or 0,averageLoss=m.losses>0 and m.loss/m.losses or 0,maxStreak=m.maxStreak,unknown=m.unknown}end function M.backtest(rows,stock,strategy,first,last,prepared)local capital,cash=1000000,1000000 local m=M.metrics(capital)local p,owned,lastExit=nil,nil,-math.huge local pauseUntil,blocked=0,false local riskBook={}if env.risk then env.risk.Init(riskBook,{},"paper")end local function observe(net,time)if env.risk then env.risk.Record(riskBook,{net=net,time=time,strategy=strategy,sym=stock.sym})end end first,last=math.max(first or 36,36),last or#rows for i=first,last do if env.yield and i%48==0 then env.yield()end local c,prev=rows[i],rows[i-1]local now=c.s local ind=prepared and prepared[i-1]or M.indicators(rows,i-1)local open=config.marketOpen(stock.market,now)if p and open then local reason=M.exit(p,owned,prev.c,now,stock,ind)if reason or i==last or(blocked and settings.lossAction=="close")then local exitPrice=c.o*(1+(p.side=="long"and-1 or 1)*settings.slippage)local net,_,gross,fee=M.mark(p,owned,exitPrice)local payout=math.max(0,p.margin+gross-fee)net=payout-p.margin-owned.entryFee cash=cash+payout observe(net,now);M.record(m,net);p,owned,lastExit=nil,nil,now if settings.maxLossStreak and m.streak>=settings.maxLossStreak then pauseUntil=now+settings.lossPause end end end if not p and not blocked and now>=pauseUntil and open and i<last and now-lastExit>=30 and M.toClose(stock,now)>=settings.entryBuffer and now-(prev.s+config.CandleSeconds)<=config.CandleSeconds*1.5 then local item=M.signal(ind,prev.c,strategy)if item and env.adaptive then local recent={}for j=math.max(1,i-60),i-1 do recent[#recent+1]=rows[j]end local regime=env.adaptive.Regime(recent,ind,prev.c)if not env.adaptive.Compatible(strategy,regime)then item=nil end if item and strategy=="reversion"and math.abs(prev.c-ind.mean)/prev.c<item.target+config.FeeRate+settings.exitFee+2*settings.slippage then item=nil end end if item then item.sym=stock.sym end if item and env.risk and not env.risk.Allowed(riskBook,item,now)then item=nil end if item and item.side=="short"and(settings.short==false or(env.state and env.state.level()<config.ShortLevel))then item=nil end if item then item.sym=stock.sym local margin=M.size(cas