return function(env)local A,settings=env.analysis,env.settings local M={}local function update(groups,key,item,symbol)if not key then return end local r=groups[key]or{count=0,net=0,profit=0,loss=0,streak=0}groups[key]=r local net=item.riskNet or item.net if A.finite(item.reported)then net=math.min(net,item.reported)end r.count,r.net=r.count+1,r.net+net if net<0 then r.loss,r.streak=r.loss-net,r.streak+1 elseif net>0 then r.profit,r.streak=r.profit+net,0 end if symbol and net<0 then r.untilTime=math.max(r.untilTime or 0,item.time+math.max(180,settings.lossPause))end local limit=symbol and 2 or settings.maxLossStreak if not r.blocked and r.net<0 and(r.streak>=limit or(r.count>=5 and r.profit<r.loss*0.7))then r.blocked,r.blockedAt=true,item.time r.reason=symbol and"종목 반복 손실 · 세션 신규 진입 차단"or"전략 반복 손실 · 세션 신규 진입 차단"end end function M.Record(b,item)if not A.finite(item.net)or not A.finite(item.time)then return end local g=b.riskState assert(g,"위험 일지 초기화 필요")g.count=g.count+1 update(g.strategies,item.strategy,item,false)update(g.symbols,item.sym,item,true)update(g.directions,item.side,item,false)update(g.leverages,item.leverage and tostring(item.leverage),item,false)g.recent[#g.recent+1]=item.riskNet or item.net while#g.recent>12 do table.remove(g.recent,1)end end function M.Init(b,trades,mode)if b.riskState and b.riskState.version==2 then return end local old=b.riskState b.riskState={version=2,count=0,strategies={},symbols={},directions={},leverages={},recent={},mode=mode}local sorted={}for _,t in ipairs(trades)do if t.mode==mode then sorted[#sorted+1]=t end end table.sort(sorted,function(a,c)return a.time<c.time end)for _,t in ipairs(sorted)do M.Record(b,t)end if old then for _,category in ipairs({"strategies","symbols"})do for key,guard in pairs(old[category]or{})do if guard.blocked then b.riskState[category][key]=guard end end end end end function M.Allowed(b,item,now)local g=b.riskState if not g then return false,"위험 일지 미확인"end local strategy,symbol=g.strategies[item.strategy],g.symbols[item.sym]if strategy and strategy.blocked then return false,strategy.reason end if symbol and symbol.blocked then return false,symbol.reason end if symbol and now<(symbol.untilTime or 0)then return false,"종목 손실 후 최소 180초 대기"end local direction=g.directions[item.side]if direction and direction.blocked then return false,"거래 방향 반복 손실 · 신규 진입 차단"end local leverage=item.leverage and g.leverages[tostring(item.leverage)]if leverage and leverage.blocked then return false,"해당 배율 반복 손실 · 신규 진입 차단"end if#g.recent>=8 then local sum,losses=0,0 for _,net in ipairs(g.recent)do sum=sum+net;if net<0 then losses=losses+1 end end if sum<0 and losses/#g.recent>=0.75 then return false,"최근 비용 반영 성과 악화 · 신규 진입 차단"end end return true end function M.Scale(b,item)local g=b.riskState local strategy,symbol=g.strategies[item.strategy],g.symbols[item.sym]return((strategy and strategy.net<0)or(symbol and symbol.net<0))and 0.5 or 1 end return M end
