n return false,"주문 복구 상태를 먼저 확인하세요."end bot:Event("policy","시험 진입 "..(env.settings.exploratory and"활성 · 수익성 미검증 · 1배 / 위험 최대 0.15% / 1개 / 60초 간격 / 연속 2패 중지"or"비활성 · 과거 검증 통과 전략만 실제 주문").." · Live는 전진 검증 전 판단 가중치 0","Info",mode)bot:Event("started",experimental and"실험 전략 운용 시작 · 검증된 성과가 아닙니다."or"자동매매 V4.4 시작 · 초단타 독립 평가 · 배율은 위험 상한 적용","Info",mode)return true end function M.Export()local function api(name)local value=env.shared[name]or _G[name]if type(value)=="function"then return value end local bridge=env.shared.UAI_BRIDGE local caps=bridge and bridge.env and bridge.env.caps return caps and caps.fn and caps.fn[name]end local write,read,exists,mkdir,isdir=api("writefile"),api("readfile"),api("isfile"),api("makefolder"),api("isfolder")assert(type(write)=="function"and type(read)=="function"and type(exists)=="function"and type(mkdir)=="function"and type(isdir)=="function","writefile/readfile/isfile/makefolder/isfolder API가 필요합니다")local dir="UAI/hangang-v4_4"if not isdir("UAI")then mkdir("UAI")end if not isdir(dir)then mkdir(dir)end local stem,suffix=dir.."/session-"..tostring(os.time()),0 local filename=stem..".json"while exists(filename)do suffix=suffix+1;filename=stem.."-"..suffix..".json"end local bot,session=env.bot,env.bot.session local data=game:GetService("HttpService"):JSONEncode({version="4.4",quickResearch=env.quick.Data(),leverage=env.leverage.Limits(env.state.level()),liveInformation=env.live.Data(),riskState={live=session.live.riskState,paper=session.paper.riskState},performance=bot.performance,decisions=bot.decisions,placeId=game.PlaceId,exportedAt=env.state.now(),settings=env.settings,history=session.history,reports=session.reports,trades=session.trades,logs=session.logs,events=session.events,forward=env.forward.Data(),telemetry=env.telemetry and env.telemetry.Summary(),execution=session.execution,curve=env.telemetry and env.telemetry.samples,snapshot=bot:Snapshot()})write(filename,data)assert(read(filename)==data,"저장 후 내용 검증 실패")return filename end retu