return function(env)local A,config,settings=env.analysis,env.config,env.settings local M={}local regimeCache=setmetatable({},{__mode="k"})function M.Regime(rows,ind,price)if not ind or not A.finite(price)or price<=0 then return{name="비정상 시세",blocked=true}end local cached=regimeCache[ind]if not cached then local recent={}for i=math.max(1,#rows-59),#rows do recent[#recent+1]=rows[i]end local old,new,count=0,0,0 for i=2,#recent do local r=math.log(recent[i].c/recent[i-1].c)if i<=#recent-12 then old=old+r*r;count=count+1 else new=new+r*r end end cached={stats=A.statistics(recent),ratio=count>0 and old>0 and math.sqrt((new/12)/(old/count))or 1}regimeCache[ind]=cached end local stats,ratio=cached.stats,cached.ratio local directional=math.abs(ind.fast-ind.slow)/math.max(ind.atr,1e-9)local abnormal=(ratio>2 and ind.volatility>0.03)or ind.volatility>0.06 or math.abs(price/ind.close-1)>math.max(0.03,ind.volatility*4)local threshold=stats.approximateThreshold or 1 local reverting=(stats.acf1 and stats.acf1<-threshold)or(stats.deviationNextReturn and stats.deviationNextReturn<-threshold)local trend=directional>=0.6 and stats.persistence>=0.5 and(not stats.acf1 or stats.acf1>-threshold)local direction=ind.fast>ind.slow and"상승 추세"or"하락 추세"local base=trend and direction or reverting and"평균 회귀 가능 구간"or"횡보"return{name=abnormal and"비정상 시세"or base,blocked=abnormal,base=base,trend=trend,reversion=not trend and reverting or false,volatility=ratio>1.5 and"변동성 확대"or ratio<0.67 and"변동성 축소"or"변동성 유지",volatilityRatio=ratio,formation=trend and((ind.oldFast-ind.oldSlow)*(ind.fast-ind.slow)<=0 and"새 추세 형성"or"추세 유지")or math.abs(price-ind.mean)>2*ind.sd and"평균 이탈"or"방향 불명확",acf1=stats.acf1,persistence=stats.persistence,statistics=stats,directional=directional,prediction="관측 통계 · 서버 예측 가능성 미확인"}end function M.Compatible(strategy,regime)return not regime.blocked and((strategy=="trend"and regime.trend)or(strategy=="reversion"and regime.reversion))or false end function M.Diagnose(report)if type(report)~="table"then return{"검증 보고서 갱신 대기"}end local lines={}if not report.reports then return{report.reason or"훈련·평가 데이터 부족"}end for _,strategy in ipairs({"trend","reversion"})do local r=report.reports[strategy]if r then local train,test=r.training,r.test lines[#lines+1]=string.format("%s: 훈련 %d건/순손익 %.0f · 평가 %d건/순손익 %.0f · 낙폭 %.2f%%",strategy,train.trades,train.net,test.trades,test.net,test.drawdown*100)if train.trades<8 then lines[#lines+1]=strategy.." 훈련 거래 8건 미달"end if train.returnRate<=0 then lines[#lines+1]=strategy.." 훈련 비용 반영 손실 또는 무거래"end if test.trades<4 then lines[#lines+1]=strategy.." 분리 평가 거래 4건 미달"end if test.net<=0 then lines[#lines+1]=strategy.." 분리 평가 순손익 양수 미달"end if test.drawdown>=0.05 then lines[#lines+1]=strategy.." 분리 평가 낙폭 5% 이상"end if(test.profitFactor or(test.noLoss and 2 or 0))<=1.1 then lines[#lines+1]=strategy.." 분리 평가 손익계수 1.1 미달"end end end local ok,why=env.autopilot.ReportEligible(report)lines[#lines+1]=ok and"분리·순차 승인 통과"or why return lines end function M.Select(rows,ind,price,report,fresh,performance)local regime=M.Regime(rows,ind,price)local result={regime=regime,checks={},diagnostics=M.Diagnose(report)}if regime.blocked then return nil,"비정상 시세",result end local approved,why=env.autopilot.ReportEligible(fresh and report or nil)result.approved,result.validationReason=approved,why local choices={}if approved then choices[#choices+1]=report.selected end for _,strategy in ipairs({"trend","reversion"})do if not approved or strategy~=report.selected then choices[#choices+1]=strategy end end local lastReason="실시간 매매 조건 불충족"for _,strategy in ipairs(choices)do local compatible=settings.strategy~="adaptive"or M.Compatible(strategy,regime)local item,reason=A.signal(ind,price,strategy)local verified=approved and strategy==report.selected if item and strategy=="reversion"then local cost=config.FeeRate+settings.exitFee+2*settings.slippage if math.abs(price-ind.mean)/price<item.target+cost then item,reason=nil,"평균까지 회복 여유가 비용·익절 목표보다 부족"end end local