return function(env)local A,state,config=env.analysis,env.state,env.config local M={}local data={items={},seen={},pending={},samples={},models={},lastSample={},breadth=0,events={},version=1}local horizons={15,30,60}local function clean(v)return type(v)=="string"and v:sub(1,400):gsub("<[^>]*>","")or""end local function contains(text,word)return text:find(word,1,true)~=nil end local function direction(text,good)local up,down=good==true,good==false for _,word in ipairs({"순매수","매수","호재","수주","서프라이즈","상승","폭등"})do if contains(text,word)then up=true end end for _,word in ipairs({"순매도","공매도","쇼크","리콜","유상증자","하락","폭락"})do if contains(text,word)then down=true end end return up==down and 0 or up and 1 or-1 end function M.Reset(value)local signature=table.concat({tostring(config.FeeRate),tostring(env.settings.exitFee),tostring(env.settings.slippage)},"|")if type(value)=="table"and value.version==1 and value.costSignature==signature then data=value else data={items={},seen={},pending={},samples={},models={},lastSample={},breadth=0,events={},version=1}end data.costSignature=signature return data end local function fresh(sym,now)if not env.bot then return true end local q=env.bot.quoteTimes[sym]return env.bot:FeedHealthy()and q and A.finite(q.time)and math.abs(now-q.time)<=5 and os.clock()-q.clock<=5 end function M.Ingest(payload,received)if type(payload)~="table"or type(payload.headline)~="string"or not A.finite(received)then return false end local headline,tag=clean(payload.headline),clean(payload.tag)local key=tag.."|"..tostring(payload.stock or"").."|"..headline if data.seen[key]and received-data.seen[key]<300 then return false end data.seen[key]=received local kind=(contains(tag..headline,"찌라시")or contains(tag..headline,"루머")or contains(tag..headline,"소문"))and"rumor"or tag=="수급"and"flow"or tag=="시황"and"sentiment"or"news"local item={key=key,received=received,headline=headline,tag=tag,kind=kind,direction=direction(headline,payload.good),symbols={},source="Remotes.News",sourceTime=nil,sourceTimeKnown=false,truth=kind=="rumor"and"미확인 소문"or"서버 뉴스 채널 · 내용의 진위 미확인"}for _,stock in ipairs(config.Stocks)do if payload.stock==stock.sym or(stock.name and contains(headline,stock.name))or contains(headline,stock.sym)then item.symbols[#item.symbols+1]=stock.sym end end data.items[#data.items+1]=item while#data.items>120 do table.remove(data.items,1)end for _,sym in ipairs(item.symbols)do local price,previous=state.prices[sym],data.lastSample[sym]if A.finite(price)and price>0 and fresh(sym,received)then item.beforeMove=previous and received-previous.time<=5 and price/previous.price-1 or nil local group=kind data.embargo=data.embargo or{}if item.direction~=0 and received>=(data.embargo[group]or 0)then data.embargo[group]=received+60 data.pending[#data.pending+1]={key=key,kind=kind,sym=sym,time=received,price=price,direction=item.direction,outcomes={},beforeMove=item.beforeMove}end end end while#data.pending>120 do table.remove(data.pending,1)end return true end local function estimate(samples,first,last,horizon)local n,sum,square,wins=0,0,0,0 for i=first,last do local v=samples[i].outcomes[tostring(horizon)]if v then n=n+1;sum=sum+v;square=square+v*v;if v>0 then wins=wins+1 end end end if n<30 then return{n=n,passed=false}end local mean=sum/n local se=math.sqrt(math.max(0,(square-sum*sum/n)/(n-1))/n)local z,p=2.64,wins/n local lowerWin=(p+z*z/(2*n)-z*math.sqrt((p*(1-p)+z*z/(4*n))/n))/(1+z*z/n)return{n=n,mean=mean,lower=mean-2.64*se,lowerWin=lowerWin,passed=mean-2.64*se>0 and lowerWin>0.5}end function M.Train()for _,kind in ipairs({"news","flow","sentiment","rumor"})do local samples=data.samples[kind]or{}table.sort(samples,function(a,b)return a.time<b.time end)local model=data.models[kind]or{status="전진 표본 부족 · 판단 가중치 0",active=false}if not model.horizon and#samples>=30 then local best=-math.huge for _,h in ipairs(horizons)do local e=estimate(samples,1,30,h)if e.mean and e.mean>best then best=e.mean;model.horizon,model.training=h,e end end end if model.horizon and#samples>=60 then model.evaluation=estimate(samples,31,60,model.horizon)model.active=kind~="rumor"and model.training.passed and model.evaluation.passed if#samples>=90 then model.monitor=estimate(samples,#samples-29,#samples,model.horizon)model.active=model.active and model.monitor.passed end model.status=model.active and"전진 분리 평가 통과 · 반대 신호 보류에만 사용"or"비용·불확실성 기준 미달 · 판단 가중치 0"end model.count=#samples;data.models[kind]=model end end function M.Tick(now)local rising,falling=0,0 for _,stock in ipairs(config.Stocks)do local sym,price=stock.sym,state.prices[stock.sym]if A.finite(price)and price>0 and config.marketOpen(stock.market,now)and fresh(sym,now)then local prev=data.lastSample[sym]if prev then if price>prev.price then rising=rising+1 elseif price<prev.price then falling=falling+1 end end data.lastSample[sym]={time=now,price=price}end end if rising+falling>0 then data.breadth=(rising-falling)/(rising+falling)end data.events={}for _,event in ipairs(state.events or{})do local stock=type(event)=="table"and config.Stocks[event.stockIndex]if stock and A.finite(event.start)and A.finite(event.finish)and now>=event.start and now<=event.finish then data.events[#data.events+1]={id=event.id,sym=stock.sym,start=event.start,finish=event.finish,mult=event.mult,meaning="공개 이벤트 · 가격 생성과 인과관계 미확인"}end end local cost=config.FeeRate+env.settings.exitFee+2*env.settings.slippage for i=#data.pending,1,-1 do local p=data.pending[i]local price=state.prices[p.sym]local stock=state.stock and state.stock(p.sym)local valid=A.finite(price)and price>0 and fresh(p.sym,now)and(not stock or config.marketOpen(stock.market,now))for _,horizon in ipairs(horizons)do if not p.outcomes[tostring(horizon)]and now>=p.time+horizon and now-(p.time+horizon)<=3 and valid then p.outcomes[tostring(horizon)]=p.direction*(price/p.price-1)-cost end end if now>=p.time+60 then if p.outcomes["15"]and p.outcomes["30"]and p.outcomes["60"]then local samples=data.samples[p.kind]or{};data.samples[p.kind]=samples samples[#samples+1]=p if#samples>180 then table.remove(samples,61)end end table.remove(data.pending,i)end end for key,time in pairs(data.seen)do if now-time>600 then data.seen[key]=nil end end if now>=(data.nextTrain or 0)then data.nextTrain=now+30;M.Train()end end function M.Decide(sym,side,now)if not fresh(sym,now)then return true,"Live 종목 시세 지연 · 가격 전략의 신선도 검사 유지"end if not env.settings.liveInformation then return true,"Live 반영 비활성 · 가격 전략 사용"end local directionValue=side=="long"and 1 or-1 for i=#data.items,1,-1 do local item=data.items[i]local model=data.models[item.kind]if model and model.active and now>=item.received and now-item.received<=model.horizon then for _,target in ipairs(item.symbols)do if target==sym and item.direction*directionValue<0 then return false,"전진 검증 Live 정보와 반대 · 진입 보류",item.key end end end end return true,"Live 유효 근거 없음 또는 동의 · 가격·비용·위험 기준 그대로 적용"end function M.Summary(now)local latest={}for i=#data.items,1,-1 do local item=data.items[i]if not latest[item.kind]then latest[item.kind]=string.format("%s · 수신 %.0f초 전 · %s · %s",item.headline,math.max(0,now-item.received),item.direction==1 and"긍정"or item.direction==-1 and"부정"or"중립",item.truth)end end local lines={"📰 최근 주요 뉴스: "..(latest.news or"수신 없음"),"👀 현재 주목 중인 찌라시: "..(latest.rumor or"수신 없음"),"📊 시장 수급 상태: "..(latest.flow or"수신 없음").." · 텍스트 정보 / 매수·매도 수량 없음","📈 현재 시장 분위기: "..(latest.sentiment or"수신 없음")..string.format(" · 현재 틱 상승/하락 폭 %.0f%% (가격 기반)",data.breadth*100)}for _,kind in ipairs({"news","rumor","flow","sentiment"})do local m=data.models[kind]local labels={news="뉴스",rumor="찌라시",flow="수급",sentiment="시황"}lines[#lines+1]=labels[kind]..": "..(m and m.status or"수집 대기 · 판단 가중치 0").." · 독립 완료 표본 "..tostring(m and m.count or 0)end lines[#lines+1]="🤖 뉴스 단독 주문 없음 · 원문 발생 시각·가격 생성 인과 미확인 · 오래된 정보는 가격 전략으로 전환"return table.concat(lines,"\n")end M.Data=function()return data end return M end
