ply~=nil complete[7],complete[8]=journal.kind=="close",journal.kind=="close"local response=not journal.reply and"응답 대기"or(journal.reply.callOk and journal.reply.accepted==true and"서버 승인 · 실제 보유 대조 대기"or"응답 이상 · 일지 확인 필요")order=string.format("게임 실제 %s · %s %s · 증거금 %.0f · %d배\n경과 %.1f초 · %s%s",journal.kind=="open"and"진입"or"청산",p.sym,p.side=="long"and"LONG"or"SHORT",p.margin,p.leverage,math.max(0,clock-journal.started),response,journal.recovery and" · 복구 필요 / 재전송 금지"or"")elseif enabled and count>0 and bot.exits then stage=8 elseif enabled and bot.entries then stage=bot.lastTickStamp and 3 or 1 end local confirmed=bot.lastConfirmed if confirmed and confirmed.mode==session.mode and clock-confirmed.clock<=3 and not journal then complete[confirmed.kind=="open"and 7 or 9]=true if enabled and not errorState and healthy then icon,stateText="🟢",confirmed.kind=="open"and"포지션 확인 완료"or"청산 확인 완료"end end local flow={}for i,label in ipairs(stages)do if i==7 and session.mode=="paper"then label="가상 포지션 확인"end flow[#flow+1]="["..(stage==i and"● "or complete[i]and"✓ "or"○ ")..label.."]"end local global if errorState then global="오류 또는 복구 필요 · "..bot.message elseif not healthy then global="시세 데이터 부족 또는 지연"elseif journal then global="기존 주문 결과 확인 중 · 신규 주문 금지"elseif not enabled then global="전체 중지"elseif not bot.entries then global="신규 진입 중지 · 자동 청산 감시만 활성"elseif b.lossBlocked then global="세션 손실 한도 도달"elseif b.cooldownUntil>env.state.now()then global="연속 손실 제한 적용 중"elseif count>=env.settings.maxPositions or(session.mode=="live"and#env.state.data.positions>=config.MaxOpenPositions)then global="최대 보유 포지션 도달"elseif session.mode=="live"and clock<(b.nextDispatch or 0)then global="주문 쿨다운 적용 중"end local counts,opportunities,proposalMap,details={},{},{},{}for rank,item in ipairs(bot.proposals)do proposalMap[item.sym]={rank=rank,item=item}end for _,stock in ipairs(config.Stocks)do local candidate=proposalMap[stock.sym]local reason=bot.riskReasons and bot.riskReasons[stock.sym]or bot.reasons[stock.sym]or"분석 대기"local why=candidate and(global or(bot.riskReasons and bot.riskReasons[stock.sym])or"신호 조건 충족 · 위험 검증 대기")or reason local decision=bot.decisions[stock.sym]if decision then local failures={}local labels={data="데이터",validation="과거 검증",cost="거래 비용",risk="위험 한도",market="시장 운영"}for _,key in ipairs({"data","validation","cost","risk","market"})do if decision.failures[key]then failures[#failures+1]=labels[key]..": "..decision.failures[key]end end why=why..(#failures>0 and"\n"..table.concat(failures," · ")or"")..(decision.liveDecision and"\nLive: "..decision.liveDecision or"")end details[stock.sym]=why if not candidate or why~="위험 및 자금 검증 통과"then local group=category(candidate and why or reason)counts[group]=(counts[group]or 0)+1 end opportunities[#opportunities+1]={sym=stock.sym,name=stock.name or stock.sym,reason=why,rank=candidate and candidate.rank or math.huge,score=candidate and candidate.item.score or nil}end table.sort(opportunities,function(x,y)if x.rank==y.rank then return x.sym<y.sym end;return x.rank<y.rank end)local mainReason,most=nil,0 for reason,n in pairs(counts)do if n>most or(n==most and(not mainReason or reason<mainReason))then mainReason,most=reason,n end end local dots=enabled and healthy and not errorState and string.rep(".",math.floor(clock)%4)or""local now=env.state.now()local age=A.finite(now)and A.finite(env.state.t)and math.max(math.abs(now-env.state.t),clock-bot.lastTick)or nil local cycle=bot.analysisCycle local stageCounts=cycle and cycle.counts or{}local stageText=string.format("시장 열림 %d · 분석 가능 %d · 실시간 신호 %d\n과거 검증 실패 %d · 위험 실패 %d · 주문 가능 %d · 시장 마감 %d\n복수 원인은 종목별 상세에 별도 기록",stageCounts.open or 0,stageCounts.analyzable or 0,stageCounts.signals or 0,stageCounts.validationFailed or 0,stageCounts.riskFailed or 0,(global or not bot.entries)and 0 or stageCounts.orderable or 0,stageCounts.closed or 0)return{snapshot=ok and s or nil,snapshotError=not ok and tostring(s)or nil,compact=icon.." "..stateText..dots,hud=string.format("%s %s%s\n%s · 자동매매 %s · 신규 진입 %s · 자동 청산 %s\n서버 시세 %s · 마지막 Tick %s · 수신 지연 %s%s\n현재 분석/판단: %s\n자동 포지션 %d개 · %s\n%s",icon,stateText,dots,session.mode=="live"and"게임 실제 매매"or"가상 매매 · 서버 주문 없음",enabled and"활성"or"비활성",bot.entries and"허용"or"중지",bot.exits and"활성"or"중지",healthy and(bot.lastTickStamp and"연결 정상"or"초기 상태 확인 · Tick 대기")or"수신 지연/중단",bot.lastTickStamp or"실행 후 수신 없음",age and string.format("%.1f초",age)or"미확인",bot.lastTickStamp and clock-bot.lastTick<1 and" · ↻ 새 시세"or"",bot.activity,count,bot.phase,bot.message),order=order,flow=table.concat(flow," → ").."\n✓ 실제 완료/관측 · ● 현재 처리 · ○ 미진행 · 단계는 각 작업 기준\n"..(journal and"시간 경과는 체결 근거가 아닙니다."or bot.analysisBusy and"백테스트 작업 중"or enabled and"다음 시세·신호 판단 대기"or"자동매매 중지 · 분석 결과는 조회용"),summary=stageText.."\n"..string.format("%d종목 분석 완료 · 신호 조건 충족 %d개 (자금 검증 전)\n주요 진입 보류 원인: %s\n상세 사유는 실시간 분석 탭에서 확인",cycle and cycle.count or 0,cycle and cycle.signals or 0,global or mainReason or"진입 검증 진행 · 신호 발생이 주문을 보장하지 않음"),opportunities=opportunities,details=details,events=session.events,icon=icon,enabled=enabled,stage=stage,blockReason=global,}end return M end
