factories["notifications"] = (function()
return function(env)local M={}function M.Flush(window)local session=env.bot.session local cursor=session.notifiedThrough or 0 for _,event in ipairs(session.events)do if event.id>cursor and event.notify then local ok,why=pcall(function()window:Notify({Title=event.mode=="live"and"게임 실제 매매"or"가상 매매 · 서버 주문 없음",Content=event.text,Kind=event.notify,Duration=5})end)if not ok then env.bot.uiError="알림 표시 오류: "..tostring(why)end end end session.notifiedThrough=session.eventSequence end return M end
end)()
factories["mini_hud"] = (function()
return function(env)local bot,UI=env.bot,env.UI local M={}local window=UI:CreateWindow({Id=env.options.Validation and"hangang-v4-validation-hud"or"hangang-v4-hud",Title="한강 · 미니 모니터",Subtitle="숨겨도 매매는 계속됩니다",Width=300,Height=360,Theme="CodexDark",Locale="ko",GameName="한강뷰 드림",ThemeToggle=false,Search=false,ToggleKey=false,CloseBehavior="Minimize"})bot.miniWindow=window window:SetGeometry({width=300,height=360,x=16,y=60})local section=window:Tab({Id="hud",Title="실시간"}):Section({Title="자동 거래"})local status=section:Label({Id="mini-status",Text="⚪ 전체 중지"})local cash=section:Label({Id="mini-cash",Text="게임 머니 조회 중"})local profit=section:Badge({Id="mini-profit",Text="현재 예상 손익",Default="+0",Kind="Success"})local loss=section:Badge({Id="mini-loss",Text="현재 예상 손익",Default="0",Kind="Danger",Visible=false})local confirmed=section:Label({Id="mini-confirmed",Text="서버 보고 청산손익 없음"})local quick=section:Label({Id="mini-quick",Text="초단타 평가 대기"})section:Button({Id="mini-open",Text="전체 화면 열기",ActionText="열기",Style="Primary",Callback=function()bot.hudPinned,bot.hudHidden=false,false;bot.window:Show();window:Hide()end})section:Button({Id="mini-pause",Text="일시 정지 · 기존 거래 보호 유지",ActionText="일시 정지",Callback=function()bot:PauseEntries()end})section:Button({Id="mini-hide",Text="HUD만 숨기기 · 매매 계속",ActionText="숨기기",Callback=function()bot.hudHidden=true;window:Hide()end})local cache={}local function text(handle,value)if cache[handle]~=value then handle:SetText(value);cache[handle]=value end end local function value(handle,amount)if cache[handle]~=amount then handle:Set(amount,true);cache[handle]=amount end end local negative,wasShown function M.Render(monitor)if not window.Alive then return end if wasShown and not window.Visible then bot.hudHidden=true end if bot.hudHidden and window.Visible then bot.hudHidden=false end local show=not bot.hudHidden and(not bot.window.Visible or bot.hudPinned)wasShown=show if show then window:Show()else window:Hide();return end local s=monitor.snapshot text(status,monitor.compact.."\n게임 실제 거래 "..tostring(s and s.livePositionCount or 0).."개")text(cash,"게임 머니 "..(s and string.format("%.0f",s.gameCash)or"미확인"))if s then local p=s.positions[1]text(quick,(s.autoMode=="QUICK PROFIT"and"초단타 전용"or s.autoMode=="RESEARCH"and"가상 평가"or"스마트 자동").."\n"..(p and p.sym..(p.side=="long"and" 상승 "or" 하락 ")..tostring(p.leverage).."배"or"포지션 대기").."\n신규 진입 "..(s.entries and not s.lossBlocked and not s.livePending and"검토 중"or"차단"))local net=s.mode=="live"and s.unrealized or s.liveUnrealized if net~=nil then local isNegative=net<0 if negative~=isNegative then profit:SetVisible(not isNegative);loss:SetVisible(isNegative);negative=isNegative end value(isNegative and loss or profit,string.format("%+.0f (추정)",net))else profit:SetVisible(false);loss:SetVisible(false);negative=nil text(status,monitor.compact.."\n실제 매매 평가손익 미확인")end text(confirmed,"서버 보고 청산손익 "..(s.liveExecutionReported~=nil and string.format("%+.0f",s.liveExecutionReported)or"없음").."\n비용 포함 여부 미확인")else profit:SetVisible(false);loss:SetVisible(false);negative=nil text(confirmed,"계좌 데이터 미확인 · 이전 수치는 표시하지 않습니다")end end window:OnDestroy(function()bot.hudHidden=true end)window:Hide()M.window=window return M end
