local env = {options=options}
local loaded, loading = {}, {}
function env.require(id)
	if loaded[id] ~= nil then return loaded[id] end
	assert(factories[id] and not loading[id], "모듈 로드 오류: " .. tostring(id))
	loading[id] = true
	local value = factories[id](env)
	loading[id], loaded[id] = nil, value
	return value
end
return env.require("entry")
